"""Evidence-layered body location explorer; coordinates are schematic."""
import json, html
E=html.escape

def render(root):
    data=json.loads((root/'body-locations.json').read_text())
    panels=[]
    for d in data:
        links=' · '.join(f'<a href="{E(s["url"])}">{E(s["label"])}</a>' for s in d['sources'])
        panels.append(f'<article class="body-evidence" id="body-{d["id"]}" data-layer="{d["layer"]}" data-regions="{" ".join(d["regions"])}"><p class="body-kind">{E(d["evidence"])}</p><h3>{E(d["title"])}</h3><p class="body-finding">{E(d["finding"])}</p><p>{E(d["description"])}</p><p class="body-limit">{E(d["limit"])}</p><p class="body-sources">{links}</p></article>')
    return '''<section id="body" class="atlas-section"><div class="atlas-heading"><h2>Locating mind, self and soul.</h2><p>The same body can carry different answers. Explore reported locations, gestures and historical accounts. Each layer keeps its own evidence visible.</p></div><div class="body-layers" role="group" aria-label="Evidence layer"><button type="button" data-body-layer="research" aria-pressed="true">Research</button><button type="button" data-body-layer="language" aria-pressed="false">Language &amp; gestures</button><button type="button" data-body-layer="history" aria-pressed="false">Historical beliefs</button></div><div class="body-explorer"><figure class="body-figure"><svg viewBox="0 0 500 610" role="img" aria-labelledby="body-svg-title body-svg-desc"><title id="body-svg-title">Body locations in selected accounts of mind, self and soul</title><desc id="body-svg-desc">A schematic person with head and chest regions. The selected evidence explains which regions are highlighted; marker size does not represent frequency.</desc><g class="body-outline"><path d="M219 115 C196 100 191 74 202 48 C211 25 242 17 263 31 C285 44 291 74 278 98 L269 115 L271 136 C292 140 316 150 329 173 C343 199 349 241 355 283 L371 339 C376 356 364 367 354 356 L331 309 L313 250 L310 307 C309 332 302 351 297 367 L292 445 L289 553 C289 568 275 571 270 557 L252 446 L245 391 L239 446 L221 557 C217 571 202 568 202 553 L198 445 L192 367 C186 349 181 331 180 307 L177 250 L159 309 L136 356 C126 367 114 356 119 339 L135 283 C142 241 148 199 161 173 C174 150 198 140 218 136 Z"/><path d="M218 136 Q245 155 271 136 M219 115 Q244 128 269 115 M193 310 Q244 329 298 310"/></g><g class="body-zone is-active" data-zone="head"><ellipse cx="242" cy="71" rx="32" ry="39"/><circle cx="242" cy="70" r="7"/><path d="M273 70 H366"/><text x="377" y="76">Head</text></g><g class="body-zone" data-zone="chest"><ellipse cx="243" cy="203" rx="41" ry="31"/><circle cx="243" cy="202" r="7"/><path d="M283 202 H355"/><text x="367" y="198">Chest /</text><text x="367" y="219">heart area</text></g></svg><figcaption id="body-map-caption">Head highlighted. Schematic locations; markers do not show anatomical boundaries or response percentages.</figcaption></figure><div class="body-reading"><div class="body-cases" role="group" aria-label="Choose an account">'''+''.join(f'<button type="button" data-body-case="{d["id"]}" data-layer="{d["layer"]}" aria-controls="body-{d["id"]}" aria-pressed="false">{E(d["label"])}</button>' for d in data)+'''</div><div id="body-evidence-panels">'''+''.join(panels)+'''</div><p class="body-status" id="body-status" role="status" aria-live="polite"></p></div></div><p class="semantic-key">A reported location, a conventional sign and a historical belief answer different questions. This explorer presents selected evidence, not a worldwide map of where consciousness resides.</p></section>'''
